begin;
select no_plan();
insert into auth.users(id) values ('70000000-0000-4000-8000-000000000001'),('70000000-0000-4000-8000-000000000002');
create function pg_temp.uid() returns uuid language sql as $$select '70000000-0000-4000-8000-000000000001'::uuid$$;
create function pg_temp.grant(p_key text, p_amount bigint, p_expiry timestamptz default null) returns app.credit_ledger language sql as $$
 select app.grant_credits(pg_temp.uid(),p_amount,'signup_grant','test',null,p_key,p_expiry)
$$;
create function pg_temp.reserve(p_key text, p_amount bigint) returns app.credit_reservations language sql as $$
 select app.reserve_credits(pg_temp.uid(),null,p_amount,p_key)
$$;
select is((pg_temp.grant('g1',20)).amount,20::bigint,'DB-10 grant');
select is((pg_temp.grant('g1',20)).id,(select id from app.credit_ledger where idempotency_key='g1'),'DB-10 replay');
select throws_ok($$select pg_temp.grant('g1',21)$$,'SS004','idempotency mismatch','DB-10 changed amount');
select pg_temp.grant('g2',10,now()+interval '1 day');
select pg_temp.grant('g3',10,now()+interval '2 days');
select is((pg_temp.reserve('r1',25)).amount,25::bigint,'DB-11 reserve');
select is((pg_temp.reserve('r1',25)).id,(select id from app.credit_reservations where idempotency_key='r1'),'DB-11 replay');
select throws_ok($$select pg_temp.reserve('r1',24)$$,'SS004','idempotency mismatch','DB-11 changed amount');
select throws_ok($$select pg_temp.reserve('too-much',16)$$,'SS001','insufficient credits','DB-11 insufficient');
select is((select held from app.credit_accounts where user_id=pg_temp.uid()),25::bigint,'DB-11 held');
select app.settle_reservation((select id from app.credit_reservations where idempotency_key='r1'),15);
select is((select balance from app.credit_accounts where user_id=pg_temp.uid()),25::bigint,'DB-12 balance');
select is((select held from app.credit_accounts where user_id=pg_temp.uid()),0::bigint,'DB-12 entire hold released');
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='g2'),0::bigint,'DB-12 earliest expiry consumed first');
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='g3'),5::bigint,'DB-12 next expiry partly consumed');
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='g1'),20::bigint,'DB-12 nonexpiring last');
select lives_ok($$select app.settle_reservation((select id from app.credit_reservations where idempotency_key='r1'),15)$$,'DB-12 double settle');
select is((select count(*) from app.credit_ledger where user_id=pg_temp.uid() and kind='spend'),1::bigint,'DB-12 one spend');
select throws_ok($$select app.settle_reservation((select id from app.credit_reservations where idempotency_key='r1'),14)$$,'SS004','idempotency mismatch','DB-12 changed settlement');
select is((app.release_reservation((select id from app.credit_reservations where idempotency_key='r1'),'failed')).status,'settled','DB-13 release settled no-op');
select pg_temp.reserve('r2',10);
select is((app.release_reservation((select id from app.credit_reservations where idempotency_key='r2'),'failed')).status,'released','DB-13 release');
select lives_ok($$select app.release_reservation((select id from app.credit_reservations where idempotency_key='r2'),'again')$$,'DB-13 repeated release');
select throws_ok($$select app.settle_reservation((select id from app.credit_reservations where idempotency_key='r2'),1)$$,'SS004','reservation not active','DB-13 settle released');
-- Exercise trigger even if service were accidentally granted mutation privileges.
grant update,delete,truncate on app.credit_ledger to service_role;
grant truncate on app.credit_reservations, app.credit_lots, public.generation_jobs, app.provider_calls to service_role;
set local role service_role;
select throws_ok($$update app.credit_ledger set amount=amount$$,'SS004','credit ledger is append-only','DB-14 service update');
select throws_ok($$delete from app.credit_ledger$$,'SS004','credit ledger is append-only','DB-14 service delete');
select throws_ok($$truncate app.credit_ledger cascade$$,'SS004','credit ledger is append-only','DB-14 service truncate');
reset role;
revoke update,delete,truncate on app.credit_ledger from service_role;
revoke truncate on app.credit_reservations, app.credit_lots, public.generation_jobs, app.provider_calls from service_role;
select throws_ok($$update app.credit_ledger set amount=amount$$,'SS004','credit ledger is append-only','DB-14 owner update');
select throws_ok($$delete from app.credit_ledger$$,'SS004','credit ledger is append-only','DB-14 owner delete');
select throws_ok($$truncate app.credit_ledger cascade$$,'SS004','credit ledger is append-only','DB-14 owner truncate');
select throws_ok($$select app.adjust_credits(pg_temp.uid(),-26,pg_temp.uid(),'test','bad-adjust')$$,'SS001','insufficient credits','DB-15 negative adjustment refused');
select throws_ok($$select app.grant_credits(pg_temp.uid(),-1,'signup_grant','test',null,'bad-grant')$$,'SS004','invalid grant','DB-15 negative grant refused');
select throws_ok($$select app.grant_credits(pg_temp.uid(),1,'reversal','test',null,'bad-reversal')$$,'SS004','invalid grant','DB-15 no public reversal path');
select pg_temp.reserve('oversettle',5);
select throws_ok($$select app.settle_reservation((select id from app.credit_reservations where idempotency_key='oversettle'),26)$$,'SS004','invalid settlement','DB-15 oversettle refused');
select app.release_reservation((select id from app.credit_reservations where idempotency_key='oversettle'),'test');
select is((app.refund_spend((select id from app.credit_ledger where user_id=pg_temp.uid() and kind='spend'),'failure','refund1')).amount,15::bigint,'DB-18 refund');
select lives_ok($$select app.refund_spend((select id from app.credit_ledger where user_id=pg_temp.uid() and kind='spend'),'failure','refund1')$$,'DB-18 refund replay');
select throws_ok($$select app.refund_spend((select id from app.credit_ledger where user_id=pg_temp.uid() and kind='spend'),'failure','refund2')$$,'SS004','spend already refunded','DB-18 one refund per spend');
select ok((select l.expires_at is null and remaining=15 from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='refund1'),'DB-18 refund nonexpiring lot');
select app.adjust_credits(pg_temp.uid(),-2,pg_temp.uid(),'correction','adjust1');
select app.adjust_credits(pg_temp.uid(),-2,pg_temp.uid(),'correction','adjust1');
select is((select count(*) from app.audit_log where action='credits.adjust' and target=pg_temp.uid()::text),1::bigint,'DB-18 audit once');
select ok((select actor_id=pg_temp.uid() and diff->>'reason'='correction' and diff->>'amount'='-2' from app.audit_log where action='credits.adjust' and target=pg_temp.uid()::text),'DB-18 audit actor reason amount');
select app.start_job(pg_temp.uid(),'generate','mock-music-a',5,'j1',1);
select is((app.start_job(pg_temp.uid(),'generate','mock-music-a',5,'j1',1)).id,(select id from public.generation_jobs where user_id=pg_temp.uid() and idempotency_key='j1'),'DB-17 replay at limit');
select throws_ok($$select app.start_job(pg_temp.uid(),'generate','mock-music-a',5,'j2',1)$$,'SS003','concurrency limit','DB-17 music concurrency');
select throws_ok($$select app.start_job(pg_temp.uid(),'extend','mock-music-a',5,'j1',1)$$,'SS004','idempotency mismatch','DB-17 changed job');
update public.profiles set status='suspended' where id=pg_temp.uid();
select throws_ok($$select pg_temp.reserve('restricted',1)$$,'SS002','account restricted','DB-17 suspended');
update public.profiles set status='cooldown',cooldown_until=now()+interval '1 hour' where id=pg_temp.uid();
select throws_ok($$select pg_temp.reserve('restricted',1)$$,'SS002','account restricted','DB-17 cooldown');
update public.profiles set status='active',cooldown_until=null where id=pg_temp.uid();
update app.credit_reservations set expires_at=now()-interval '1 minute' where idempotency_key='job:'||pg_temp.uid()||':j1';
update public.generation_jobs set status='running' where user_id=pg_temp.uid();
select is(app.expire_reservations(),0,'DB-18 running skipped');
update public.generation_jobs set status='finishing' where user_id=pg_temp.uid();
select is(app.expire_reservations(),0,'DB-18 finishing skipped');
update public.generation_jobs set status='failed' where user_id=pg_temp.uid();
select is(app.expire_reservations(),1,'DB-18 failed expired');
select is(app.expire_reservations(),0,'DB-18 expiry repeated');
select is((select count(*) from app.reconcile_credits()),0::bigint,'DB-18 reconciles');
select ok(has_table_privilege('service_role','app.credit_accounts','SELECT') and not has_table_privilege('service_role','app.credit_accounts','INSERT,UPDATE,DELETE,TRUNCATE'),'credit_accounts service select only');
select ok(not has_table_privilege('anon','app.credit_accounts','SELECT') and not has_table_privilege('authenticated','app.credit_accounts','SELECT'),'credit_accounts clients hidden');
select ok(has_table_privilege('service_role','app.credit_ledger','SELECT') and not has_table_privilege('service_role','app.credit_ledger','INSERT,UPDATE,DELETE,TRUNCATE'),'credit_ledger service select only');
select ok(not has_table_privilege('anon','app.credit_ledger','SELECT') and not has_table_privilege('authenticated','app.credit_ledger','SELECT'),'credit_ledger clients hidden');
select ok(has_table_privilege('service_role','app.credit_reservations','SELECT') and not has_table_privilege('service_role','app.credit_reservations','INSERT,UPDATE,DELETE,TRUNCATE'),'credit_reservations service select only');
select ok(not has_table_privilege('anon','app.credit_reservations','SELECT') and not has_table_privilege('authenticated','app.credit_reservations','SELECT'),'credit_reservations clients hidden');
select ok(has_table_privilege('service_role','app.credit_lots','SELECT') and not has_table_privilege('service_role','app.credit_lots','INSERT,UPDATE,DELETE,TRUNCATE'),'credit_lots service select only');
select ok(not has_table_privilege('anon','app.credit_lots','SELECT') and not has_table_privilege('authenticated','app.credit_lots','SELECT'),'credit_lots clients hidden');
select ok(has_table_privilege('service_role','app.signup_grants','SELECT') and not has_table_privilege('service_role','app.signup_grants','INSERT,UPDATE,DELETE,TRUNCATE'),'signup_grants service select only');
select ok(not has_table_privilege('anon','app.signup_grants','SELECT') and not has_table_privilege('authenticated','app.signup_grants','SELECT'),'signup_grants clients hidden');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='app' and p.proname in ('grant_credits','reserve_credits','settle_reservation','release_reservation','refund_spend','adjust_credits','start_job','expire_reservations','expire_credits','reconcile_credits') and has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE')),10::bigint,'RPC grants service only');
select ok(not has_function_privilege('service_role','app.post_credit_entry(uuid,bigint,text,text,uuid,text,timestamptz,jsonb)','EXECUTE'),'private posting helper');
-- Confirmation grant, same-user replay, same-email after deletion.
insert into auth.users(id,email) values ('70000000-0000-4000-8000-000000000003','ledger-confirm@example.test');
select is((select count(*) from app.credit_ledger where user_id='70000000-0000-4000-8000-000000000003'),0::bigint,'unconfirmed no grant');
update auth.users set email_confirmed_at=now() where id='70000000-0000-4000-8000-000000000003';
update auth.users set email_confirmed_at=now() where id='70000000-0000-4000-8000-000000000003';
select is((select count(*) from app.credit_ledger where user_id='70000000-0000-4000-8000-000000000003'),1::bigint,'confirmation once');
select is((select amount from app.credit_ledger where user_id='70000000-0000-4000-8000-000000000003'),30::bigint,'registry fallback 30');
delete from auth.users where id='70000000-0000-4000-8000-000000000003';
insert into auth.users(id,email,email_confirmed_at) values ('70000000-0000-4000-8000-000000000004','ledger-confirm@example.test',now());
select is((select count(*) from app.credit_ledger where user_id='70000000-0000-4000-8000-000000000004'),0::bigint,'same email cannot farm grants');
insert into app.flags(key,value) values ('signup_grant_credits','42') on conflict(key) do update set value=excluded.value;
insert into auth.users(id,email,email_confirmed_at) values ('70000000-0000-4000-8000-000000000005','ledger-flag@example.test',now());
select is((select amount from app.credit_ledger where user_id='70000000-0000-4000-8000-000000000005'),42::bigint,'configured signup grant');
-- Inject a real grant failure without changing the trigger: existing conflicting key.
select app.grant_credits(pg_temp.uid(),1,'signup_grant','test',null,'signup:70000000-0000-4000-8000-000000000006');
select lives_ok($$insert into auth.users(id,email,email_confirmed_at) values ('70000000-0000-4000-8000-000000000006','ledger-failure@example.test',now())$$,'grant failure never blocks signup');
select ok(exists(select 1 from public.profiles where id='70000000-0000-4000-8000-000000000006'),'profile usable after grant failure');

select is((select count(*) from app.signup_grants where user_id='70000000-0000-4000-8000-000000000006'),0::bigint,'failed grant rolls back eligibility claim');
select throws_ok($$select app.start_job(pg_temp.uid(),'generate','mock-music-a',5,'j1',2)$$,'SS004','idempotency mismatch','DB-17 changed limit');
select throws_ok($$select app.settle_reservation((select id from app.credit_reservations where idempotency_key='job:'||pg_temp.uid()||':j1'),1)$$,'SS004','reservation not active','DB-13 settle expired');
select pg_temp.reserve('zero',2);
select is((app.settle_reservation((select id from app.credit_reservations where idempotency_key='zero'),0)).settled_amount,0::bigint,'DB-12 zero settlement');
select lives_ok($$select app.settle_reservation((select id from app.credit_reservations where idempotency_key='zero'),0)$$,'DB-12 zero settlement replay');
select ok((select settled_ledger_id is null from app.credit_reservations where idempotency_key='zero'),'DB-12 zero settlement has no ledger row');
select throws_ok($$select app.reserve_credits(pg_temp.uid(),null,2,'zero',interval '1 minute')$$,'SS004','idempotency mismatch','DB-11 changed TTL');
select throws_ok($$select app.reserve_credits(pg_temp.uid(),null,1,'invalid',interval '0')$$,'SS004','invalid reservation','DB-11 invalid TTL');
select throws_ok($$select app.reserve_credits(pg_temp.uid(),null,0,'invalid')$$,'SS004','invalid reservation','DB-11 zero reserve');
select throws_ok($$select app.refund_spend((select id from app.credit_ledger where idempotency_key='g1'),'test','invalid')$$,'SS004','invalid spend','DB-18 cannot refund grant');
select throws_ok($$select app.refund_spend((select id from app.credit_ledger where user_id=pg_temp.uid() and kind='spend'),'changed','refund1')$$,'SS004','idempotency mismatch','DB-18 changed refund reason');
select throws_ok($$select app.adjust_credits(pg_temp.uid(),-2,pg_temp.uid(),'changed','adjust1')$$,'SS004','idempotency mismatch','DB-18 changed adjustment reason');
update public.profiles set status='banned' where id=pg_temp.uid();
select throws_ok($$select pg_temp.reserve('restricted',1)$$,'SS002','account restricted','DB-17 banned');
update public.profiles set status='deleted' where id=pg_temp.uid();
select throws_ok($$select app.start_job(pg_temp.uid(),'generate','mock-music-a',1,'restricted-job',2)$$,'SS002','account restricted','DB-17 deleted start');
update public.profiles set status='cooldown',cooldown_until=now()-interval '1 minute' where id=pg_temp.uid();
select lives_ok($$select pg_temp.reserve('lapsed',1)$$,'DB-17 lapsed cooldown allowed');
select app.release_reservation((select id from app.credit_reservations where idempotency_key='lapsed'),'test');
-- Equal-expiry and non-expiring FIFO use insertion sequence, not random UUID order.
select app.grant_credits('70000000-0000-4000-8000-000000000002',5,'signup_grant','test',null,'fifo1');
select app.grant_credits('70000000-0000-4000-8000-000000000002',5,'signup_grant','test',null,'fifo2');
select app.reserve_credits('70000000-0000-4000-8000-000000000002',null,6,'fifo-reserve');
select app.settle_reservation((select id from app.credit_reservations where idempotency_key='fifo-reserve'),6);
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='fifo1'),0::bigint,'DB-12 nonexpiring oldest first');
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='fifo2'),4::bigint,'DB-12 nonexpiring newer remainder');
update app.credit_accounts set held=held+1 where user_id=pg_temp.uid();
select ok(exists(select 1 from app.reconcile_credits() where user_id=pg_temp.uid() and "check"='held'),'reconcile held discrepancy');
update app.credit_accounts set held=held-1 where user_id=pg_temp.uid();
update app.credit_lots set remaining=remaining+1 where ledger_id=(select id from app.credit_ledger where idempotency_key='g1');
select ok(exists(select 1 from app.reconcile_credits() where user_id=pg_temp.uid() and "check"='lots'),'reconcile lot discrepancy');
update app.credit_lots set remaining=remaining-1 where ledger_id=(select id from app.credit_ledger where idempotency_key='g1');
alter table app.credit_ledger disable trigger credit_ledger_append_only;
update app.credit_ledger set balance_after=balance_after+1 where idempotency_key='g1';
select ok(exists(select 1 from app.reconcile_credits() where user_id=pg_temp.uid() and "check"='balance_after'),'reconcile chain discrepancy');
update app.credit_ledger set balance_after=balance_after-1 where idempotency_key='g1';
alter table app.credit_ledger enable trigger credit_ledger_append_only;
select is((select count(*) from app.reconcile_credits()),0::bigint,'all invariants restored');


-- DB-16: partial expiry preserves held credits, then drains the remainder once released.
insert into auth.users(id) values ('70000000-0000-4000-8000-000000000007');
select app.grant_credits('70000000-0000-4000-8000-000000000007',10,'signup_grant','test',null,'expiry-first',now()-interval '2 days');
select app.grant_credits('70000000-0000-4000-8000-000000000007',10,'signup_grant','test',null,'expiry-second',now()-interval '1 day');
select app.grant_credits('70000000-0000-4000-8000-000000000007',5,'signup_grant','test',null,'expiry-never');
select app.reserve_credits('70000000-0000-4000-8000-000000000007',null,12,'expiry-hold');
select is(app.expire_credits(),2,'DB-16 two expired portions');
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='expiry-first'),0::bigint,'DB-16 earliest lot exhausted');
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='expiry-second'),7::bigint,'DB-16 held portion retained');
select ok((select balance=12 and held=12 from app.credit_accounts where user_id='70000000-0000-4000-8000-000000000007'),'DB-16 balance never below held');
select is(app.expire_credits(),0,'DB-16 retry while held is no-op');
select app.release_reservation((select id from app.credit_reservations where idempotency_key='expiry-hold'),'test');
select is(app.expire_credits(),1,'DB-16 remaining portion expires after release');
select is(app.expire_credits(),0,'DB-16 completed expiry is no-op');
select is((select balance from app.credit_accounts where user_id='70000000-0000-4000-8000-000000000007'),5::bigint,'DB-16 nonexpiring credits survive');
select is((select sum(amount) from app.credit_ledger where user_id='70000000-0000-4000-8000-000000000007' and kind='expiry'),-20::numeric,'DB-16 no lost or duplicated expiry');
select ok(exists(select 1 from app.credit_ledger where idempotency_key='expiry:'||(select id from app.credit_ledger where idempotency_key='expiry-first')),'DB-16 first portion uses specified key');
select ok(exists(select 1 from app.credit_ledger where idempotency_key='expiry:'||(select id from app.credit_ledger where idempotency_key='expiry-second')||':7'),'DB-16 remaining portion has deterministic key');
select is((select count(*) from app.reconcile_credits()),0::bigint,'DB-16 expiry reconciles');

-- DB-15: postgres-only reversal injection; no purchase API is introduced.
insert into auth.users(id) values ('70000000-0000-4000-8000-000000000008');
select app.grant_credits('70000000-0000-4000-8000-000000000008',10,'signup_grant','test',null,'reversal-expiring',now()+interval '1 day');
select app.grant_credits('70000000-0000-4000-8000-000000000008',20,'signup_grant','test',null,'reversal-permanent');
select app.reserve_credits('70000000-0000-4000-8000-000000000008',null,20,'guaranteed-hold');
select app.post_credit_entry('70000000-0000-4000-8000-000000000008',-15,'reversal','test',null,'positive-reversal',null,'["positive-reversal"]');
select is((select balance from app.credit_accounts where user_id='70000000-0000-4000-8000-000000000008'),15::bigint,'DB-15 reversal leaves positive balance');
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='reversal-expiring'),0::bigint,'DB-15 reversal consumes earliest expiry first');
select is((select remaining from app.credit_lots l join app.credit_ledger e on e.id=l.ledger_id where e.idempotency_key='reversal-permanent'),15::bigint,'DB-15 reversal consumes remaining FIFO lots');
select is((select count(*) from app.reconcile_credits()),0::bigint,'DB-15 positive reversal reconciles despite held exceeding balance');
select app.post_credit_entry('70000000-0000-4000-8000-000000000008',-20,'reversal','test',null,'negative-reversal',null,'["negative-reversal"]');
select is((select balance from app.credit_accounts where user_id='70000000-0000-4000-8000-000000000008'),-5::bigint,'DB-15 reversal may exceed available lots');
select is((select sum(remaining) from app.credit_lots where user_id='70000000-0000-4000-8000-000000000008'),0::numeric,'DB-15 debt has zero remaining lots');
select lives_ok($$select app.settle_reservation((select id from app.credit_reservations where idempotency_key='guaranteed-hold'),20)$$,'DB-15 guaranteed settlement succeeds after negative reversal');
select ok((select balance=-25 and held=0 from app.credit_accounts where user_id='70000000-0000-4000-8000-000000000008'),'DB-15 settlement charges full amount and releases hold');
select is((select status from app.credit_reservations where idempotency_key='guaranteed-hold'),'settled','DB-15 reservation settled');
select is((select count(*) from app.reconcile_credits()),0::bigint,'DB-15 negative settlement reconciles');
select lives_ok($$select app.settle_reservation((select id from app.credit_reservations where idempotency_key='guaranteed-hold'),20)$$,'DB-15 negative settlement replay is no-op');
select is((select count(*) from app.credit_ledger where user_id='70000000-0000-4000-8000-000000000008' and kind='spend'),1::bigint,'DB-15 guaranteed settlement charged once');
select throws_ok($$select app.reserve_credits('70000000-0000-4000-8000-000000000008',null,1,'debt-reserve')$$,'SS001','insufficient credits','DB-15 FR-78 rejects new reservations in debt');
-- Reconciliation must also detect illicit lots while the balance is negative.
update app.credit_lots set remaining=1 where ledger_id=(select id from app.credit_ledger where idempotency_key='reversal-permanent');
select ok(exists(select 1 from app.reconcile_credits() where user_id='70000000-0000-4000-8000-000000000008' and "check"='lots' and expected=0 and actual=1),'DB-15 lots check covers negative balances');
update app.credit_lots set remaining=0 where ledger_id=(select id from app.credit_ledger where idempotency_key='reversal-permanent');
-- Credits received in debt cannot create spendable lots before repaying it.
select app.refund_spend((select id from app.credit_ledger where user_id='70000000-0000-4000-8000-000000000008' and kind='spend'),'test','debt-refund');
select is((select count(*) from app.reconcile_credits()),0::bigint,'DB-15 refund partially repaying debt reconciles');
select app.grant_credits('70000000-0000-4000-8000-000000000008',10,'signup_grant','test',null,'debt-repaid');
select is((select balance from app.credit_accounts where user_id='70000000-0000-4000-8000-000000000008'),5::bigint,'DB-15 incoming credits repay debt');
select is((select sum(remaining) from app.credit_lots where user_id='70000000-0000-4000-8000-000000000008'),5::numeric,'DB-15 only positive remainder becomes a lot');
select is((select count(*) from app.reconcile_credits()),0::bigint,'DB-15 recovered account reconciles');

select * from finish();
rollback;
